import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

public class GenericMergeSorterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String show(List<?> list) {
        return list == null ? "null" : list.toString();
    }

    public static void main(String[] args) {
        List<Integer> numbers = new ArrayList<>(Arrays.asList(5, 3, 9, 1, 3, 8, 0, 7));
        check("sort ints ascending", "[0, 1, 3, 3, 5, 7, 8, 9]",
                show(GenericMergeSorter.sort(numbers, Comparator.naturalOrder())));
        check("input list untouched", "[5, 3, 9, 1, 3, 8, 0, 7]", numbers.toString());
        check("sort ints descending", "[9, 8, 7, 5, 3, 3, 1, 0]",
                show(GenericMergeSorter.sort(numbers, Comparator.reverseOrder())));
        check("sortNatural on strings", "[apple, cherry, pear]",
                show(GenericMergeSorter.sortNatural(Arrays.asList("pear", "apple", "cherry"))));

        List<Contestant> people = Arrays.asList(
                new Contestant("dana", 7),
                new Contestant("ana", 5),
                new Contestant("carl", 7),
                new Contestant("bo", 5),
                new Contestant("eve", 1));
        Comparator<Contestant> byScore = Comparator.comparingInt(Contestant::score);
        check("stable sort keeps input order within equal scores",
                "[eve:1, ana:5, bo:5, dana:7, carl:7]",
                show(GenericMergeSorter.sort(people, byScore)));

        Comparator<Object> byText = Comparator.comparing(Object::toString);
        check("comparator may be on a supertype", "[ana:5, bo:5, carl:7, dana:7, eve:1]",
                show(GenericMergeSorter.<Contestant>sort(people, byText)));

        check("empty list", "[]", show(GenericMergeSorter.sortNatural(new ArrayList<String>())));
        check("single element", "[jj]", show(GenericMergeSorter.sortNatural(Arrays.asList("jj"))));
        check("null input", "[]", show(GenericMergeSorter.sortNatural(null)));
        check("already sorted stays sorted", "[1, 2, 3, 4]",
                show(GenericMergeSorter.sortNatural(Arrays.asList(1, 2, 3, 4))));
        check("reversed input", "[1, 2, 3, 4, 5]",
                show(GenericMergeSorter.sortNatural(Arrays.asList(5, 4, 3, 2, 1))));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

