import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** Provided -- a small data type used by the tests. Do not edit. */
record Contestant(String name, int score) {
    @Override
    public String toString() {
        return name + ":" + score;
    }
}

public class GenericMergeSorter {

    public static <T> List<T> sort(List<? extends T> input, Comparator<? super T> comparator) {
        List<T> working = new ArrayList<>();
        if (input == null) {
            return working;
        }
        working.addAll(input);
        if (working.size() < 2) {
            return working;
        }
        int middle = working.size() / 2;
        List<T> left = sort(working.subList(0, middle), comparator);
        List<T> right = sort(working.subList(middle, working.size()), comparator);

        List<T> merged = new ArrayList<>(working.size());
        int i = 0;
        int j = 0;
        while (i < left.size() && j < right.size()) {
            if (comparator.compare(right.get(j), left.get(i)) < 0) {
                merged.add(right.get(j));
                j++;
            } else {
                merged.add(left.get(i));
                i++;
            }
        }
        while (i < left.size()) {
            merged.add(left.get(i));
            i++;
        }
        while (j < right.size()) {
            merged.add(right.get(j));
            j++;
        }
        return merged;
    }

    public static <T extends Comparable<? super T>> List<T> sortNatural(List<? extends T> input) {
        return sort(input, (a, b) -> a.compareTo(b));
    }
}
